fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    let m = a.len();
    let n = b.len();
    let len = m.max(n);

    // Broadcast `a`
    let a_out = if m == 1 {
        vec![a[0]; len]
    } else {
        // m == len (since compatible)
        a.clone()
    };

    // Broadcast `b`
    let b_out = if n == 1 {
        vec![b[0]; len]
    } else {
        // n == len
        b.clone()
    };

    (a_out, b_out)
}